// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Updates, soft deletes and restorations record assigned or changed fields plus the key; create and delete record every field.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes RecordChanges) Audit(policy RecordAuditPolicy) (record.Model[Record, model.ID[Record]], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Record, model.ID[Record]]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Record, model.ID[Record]]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Record, model.ID[Record]]{}, err
	}
	if err = record.Capture(builder, "id", codec.ID[Record](), changes.fields.ID, policy.ID); err != nil {
		return record.Model[Record, model.ID[Record]]{}, err
	}
	if err = record.Capture(builder, "namespace", codec.String[string](), changes.fields.Namespace, policy.Namespace); err != nil {
		return record.Model[Record, model.ID[Record]]{}, err
	}
	if err = record.Capture(builder, "operation", codec.String[string](), changes.fields.Operation, policy.Operation); err != nil {
		return record.Model[Record, model.ID[Record]]{}, err
	}
	if err = record.Capture(builder, "version", codec.Unsigned[uint32](), changes.fields.Version, policy.Version); err != nil {
		return record.Model[Record, model.ID[Record]]{}, err
	}
	if err = record.Capture(builder, "scope_digest", codec.String[string](), changes.fields.ScopeDigest, policy.ScopeDigest); err != nil {
		return record.Model[Record, model.ID[Record]]{}, err
	}
	if err = record.Capture(builder, "key_digest", codec.String[string](), changes.fields.KeyDigest, policy.KeyDigest); err != nil {
		return record.Model[Record, model.ID[Record]]{}, err
	}
	if err = record.Capture(builder, "fingerprint", codec.String[string](), changes.fields.Fingerprint, policy.Fingerprint); err != nil {
		return record.Model[Record, model.ID[Record]]{}, err
	}
	if err = record.Capture(builder, "result_schema", codec.String[string](), changes.fields.ResultSchema, policy.ResultSchema); err != nil {
		return record.Model[Record, model.ID[Record]]{}, err
	}
	if err = record.Capture(builder, "result_hash", codec.String[string](), changes.fields.ResultHash, policy.ResultHash); err != nil {
		return record.Model[Record, model.ID[Record]]{}, err
	}
	if err = record.Capture(builder, "representation", codec.Bytes[[]byte](), changes.fields.Representation, policy.Representation); err != nil {
		return record.Model[Record, model.ID[Record]]{}, err
	}
	if err = record.Capture(builder, "completed_at", codec.Nullable(codec.DateTime()), changes.fields.CompletedAt, policy.CompletedAt); err != nil {
		return record.Model[Record, model.ID[Record]]{}, err
	}
	if err = record.Capture(builder, "expires_at", codec.Nullable(codec.DateTime()), changes.fields.ExpiresAt, policy.ExpiresAt); err != nil {
		return record.Model[Record, model.ID[Record]]{}, err
	}
	return builder.Build()
}

